#[unsafe(no_mangle)]
pub extern "C" fn sum_i32s(ptr: *const i32, len: usize, out_total: *mut i64) -> i32 {
    if out_total.is_null() {
        return 1;
    }

    if ptr.is_null() {
        return 2;
    }

    let slice = unsafe {
        // SAFETY:
        // - ptr is non-null and the caller promises it is valid for len i32 values.
