mod cpp_shim {
    // Rust 2024 edition syntax; on older toolchains use
    // #[no_mangle] and a plain extern "C" block.
    #[unsafe(no_mangle)]
    pub extern "C" fn cpp_route_score(ptr: *const u8, len: usize) -> u32 {
