use std::collections::{HashSet, VecDeque};

#[derive(Debug, Clone)]
struct Delivery {
    message_id: &'static str,
    order_id: &'static str,
    attempt: u8,
}

#[derive(Default)]
struct Consumer {
    processed_ids: HashSet<String>,
    retry_queue: VecDeque<Delivery>,
    dlq: Vec<Delivery>,
    processed: usize,
    duplicates: usize,
    retried: usize,
}

impl Consumer {
    fn on_delivery(&mut self, delivery: Delivery) {
        if self.processed_ids.contains(delivery.message_id) {
            self.duplicates += 1;
            return;
        }

        if delivery.order_id == "ord-fail" {
            if delivery.attempt < 3 {
                self.retried += 1;
                self.retry_queue.push_back(Delivery {
                    attempt: delivery.attempt + 1,
                    ..delivery
                });
            } else {
                self.dlq.push(delivery);
            }
            return;
        }

        self.processed += 1;
        self.processed_ids.insert(delivery.message_id.to_string());
    }
}

fn main() {
    let mut consumer = Consumer::default();

    consumer.on_delivery(Delivery {
        message_id: "msg-1",
        order_id: "ord-1",
        attempt: 1,
    });
    consumer.on_delivery(Delivery {
        message_id: "msg-1",
        order_id: "ord-1",
        attempt: 1,
    });
    consumer.on_delivery(Delivery {
        message_id: "msg-2",
        order_id: "ord-fail",
        attempt: 1,
    });

    // on_delivery may re-push to retry_queue; the attempt cap ensures this terminates.
    while let Some(delivery) = consumer.retry_queue.pop_front() {
        consumer.on_delivery(delivery);
    }

    consumer.on_delivery(Delivery {
        message_id: "msg-3",
        order_id: "ord-3",
        attempt: 1,
    });

    println!("processed = {}", consumer.processed);
    println!("duplicates = {}", consumer.duplicates);
    println!("retried = {}", consumer.retried);
    println!("dlq = {}", consumer.dlq.len());
}

distributed_tasks_lease_idempotent:
use std::collections::{HashMap, HashSet, VecDeque};

#[derive(Debug, Clone)]
struct Task {
    id: &'static str,
    payload: &'static str,
}

#[derive(Debug)]
struct Lease {
    task: Task,
    deadline: u64,
}

struct LeaseQueue {
    visible: VecDeque<Task>,
    leased: HashMap<&'static str, Lease>,
    completed: HashSet<&'static str>,
    visibility_timeout: u64,
    now: u64,
}

impl LeaseQueue {
    fn new(visibility_timeout: u64) -> Self {
        Self {
            visible: VecDeque::new(),
            leased: HashMap::new(),
            completed: HashSet::new(),
            visibility_timeout,
            now: 0,
        }
    }

    fn push(&mut self, id: &'static str, payload: &'static str) {
        self.visible.push_back(Task { id, payload });
    }

    fn claim(&mut self, worker: &'static str) -> Option<(&'static str, &'static str, &'static str)> {
        let task = self.visible.pop_front()?;
        let deadline = self.now + self.visibility_timeout;
        let task_id = task.id;
        let payload = task.payload;
        self.leased.insert(task_id, Lease { task, deadline });
        Some((worker, task_id, payload))
    }

    fn advance_time(&mut self, delta: u64) {
        self.now += delta;
    }

    fn requeue_expired(&mut self) {
        let expired: Vec<&'static str> = self
            .leased
            .iter()
            .filter(|(_, lease)| lease.deadline <= self.now)
            .map(|(&task_id, _)| task_id)
            .collect();

        for task_id in expired {
            let lease = self.leased.remove(task_id).unwrap();
            self.visible.push_back(lease.task);
        }
    }

    fn finish_once(&mut self, task_id: &'static str) -> bool {
        if !self.completed.insert(task_id) {
            return false;
        }

        self.leased.remove(task_id);
        true
    }
}

fn main() {
