zkml_proving_queue_profile:
#[derive(Debug, Clone)]
struct ZkmlJob {
    artifact_id: String,
    gpu_requested: bool,
    batch_size: usize,
}

#[derive(Debug, Clone, Copy)]
struct StageTimes {
    witness_ms: u64,
    prove_ms: u64,
    verify_ms: u64,
    transfer_ms: u64,
}

fn queue_name(job: &ZkmlJob) -> &'static str {
    if job.gpu_requested {
        "zkml.gpu"
    } else {
        "zkml.cpu"
    }
}

fn dominant_stage(times: &StageTimes) -> &'static str {
    [
        ("witness", times.witness_ms),
        ("prove", times.prove_ms),
        ("verify", times.verify_ms),
        ("transfer", times.transfer_ms),
    ]
    .into_iter()
    .max_by_key(|(_, ms)| *ms)
    .map(|(name, _)| name)
    .unwrap()
}

fn end_to_end_ms(times: &StageTimes) -> u64 {
    times.witness_ms + times.prove_ms + times.verify_ms + times.transfer_ms
}

fn main() {
    let job = ZkmlJob {
        artifact_id: String::from("model-sha256:abc123"),
        gpu_requested: true,
        batch_size: 4,
    };

    let times = StageTimes {
        witness_ms: 320,
        prove_ms: 1_280,
        verify_ms: 40,
        transfer_ms: 240,
    };

    println!("route = {}", queue_name(&job));
    println!("dominant = {}", dominant_stage(&times));
    println!("e2e ms = {}", end_to_end_ms(&times));
    println!("artifact = {}", job.artifact_id);
}

onnx_session_load_run:
// A real service would load an .onnx graph and run it through a session:
//
//   use ort::{Session, inputs};
//   let session = Session::builder()?
//       .with_optimization_level(GraphOptimizationLevel::Level3)?
//       .commit_from_file("classifier.onnx")?;
//   let outputs = session.run(inputs!["input" => input_tensor]?)?;
//
// The in-browser runner cannot call into ONNX Runtime, so this listing is a
// deterministic pure-Rust forward pass that mirrors what one dense layer of
// that graph does: a matmul against a weight matrix, a bias add, then argmax.
// The numbers, shapes, and the "predicted class" are exactly what a one-layer
// ONNX model with the same weights would produce.

const IN: usize = 4;
const OUT: usize = 3;

// Weights stored row-major: one row of IN values per output class.
const WEIGHTS: [[f32; IN]; OUT] = [
    [0.2, 0.8, -0.5, 0.1],
    [-0.3, 0.5, 0.9, 0.4],
    [0.6, -0.2, 0.3, -0.7],
];
const BIAS: [f32; OUT] = [0.1, -0.2, 0.05];

// One fixed input "tensor" of shape [IN]. In ort/tract this would be an
// ndarray Array passed in as the named input of the session.
fn input_tensor() -> [f32; IN] {
    [0.5, -1.0, 2.0, 0.25]
}

// Dense layer: logits[o] = bias[o] + sum_c weights[o][c] * input[c].
fn forward(input: &[f32; IN]) -> [f32; OUT] {
    let mut logits = [0.0f32; OUT];
    for o in 0..OUT {
        let mut sum = BIAS[o];
        for c in 0..IN {
            sum += WEIGHTS[o][c] * input[c];
        }
        logits[o] = sum;
    }
    logits
}

// Post-processing the caller owns: turn raw logits into a class index.
fn argmax(logits: &[f32; OUT]) -> usize {
    let mut best = 0;
    for i in 1..OUT {
        if logits[i] > logits[best] {
            best = i;
        }
    }
    best
}

fn main() {
    let input = input_tensor();
    let logits = forward(&input);
    let class = argmax(&logits);

    println!("input dims = {}", IN);
    println!("classes = {}", OUT);
    println!(
        "logits = [{:.4}, {:.4}, {:.4}]",
        logits[0], logits[1], logits[2]
    );
    println!("predicted class = {}", class);
    println!("score = {:.4}", logits[class]);
}

onnx_tensor_batch_argmax:
// Batched inference: the same one-layer model run over more than one row at
// once. A real session takes an input tensor of shape [rows, features] and
// returns logits of shape [rows, classes]; here we keep the batch as a single
// row-major flat Vec and slice one row at a time, with no external crates.

const IN: usize = 4;
const OUT: usize = 3;

const WEIGHTS: [[f32; IN]; OUT] = [
    [0.2, 0.8, -0.5, 0.1],
    [-0.3, 0.5, 0.9, 0.4],
    [0.6, -0.2, 0.3, -0.7],
];
const BIAS: [f32; OUT] = [0.1, -0.2, 0.05];

// Two input rows packed row-major into one flat buffer: [row0.. , row1..].
fn build_batch() -> Vec<f32> {
    vec![
        0.5, -1.0, 2.0, 0.25, // row 0
        1.5, 0.5, -0.5, 1.0, // row 1
    ]
}

// Run the dense layer over one feature row and return its logits.
fn forward_row(row: &[f32]) -> [f32; OUT] {
    assert_eq!(row.len(), IN, "row must have {IN} elements");
    let mut logits = [0.0f32; OUT];
    for o in 0..OUT {
        let mut sum = BIAS[o];
        for c in 0..IN {
            sum += WEIGHTS[o][c] * row[c];
        }
        logits[o] = sum;
    }
    logits
}

fn argmax(logits: &[f32; OUT]) -> usize {
    let mut best = 0;
    for i in 1..OUT {
        if logits[i] > logits[best] {
            best = i;
        }
    }
    best
}

fn main() {
    let batch = build_batch();
    let rows = batch.len() / IN;

    println!("batch rows = {}", rows);
    println!("features per row = {}", IN);

    for r in 0..rows {
        let row = &batch[r * IN..(r + 1) * IN];
        let logits = forward_row(row);
        let class = argmax(&logits);
        println!("row {} argmax = {} score = {:.4}", r, class, logits[class]);
    }
}

smart_contract_solana_counter:
// A hand-built model of Solana's account + instruction model, no crates.
//
// On Solana a "program" is stateless code. The state it works on lives in
// separate "accounts" that the runtime passes in as mutable byte buffers.
// An instruction tells the program which operation to run and with what data.
//
// Here we model exactly that: an Account owns a data buffer and an owner
// field, process_instruction borrows the buffer mutably, decodes a u64
// counter by hand (the way Borsh would, little-endian), applies the op, and
// writes the counter back. main() drives a couple of instructions.

#[derive(Debug)]
struct Account {
    owner: &'static str,
    data: [u8; 8],
}

#[derive(Debug)]
enum Instruction {
    Increment,
    SetTo(u64),
}

#[derive(Debug)]
enum ProgramError {
    DataTooSmall,
}

// Decode the counter the way a by-hand Borsh reader would: a little-endian u64.
fn read_counter(data: &[u8]) -> Result<u64, ProgramError> {
    if data.len() < 8 {
        return Err(ProgramError::DataTooSmall);
    }
    let mut bytes = [0u8; 8];
    bytes.copy_from_slice(&data[..8]);
    Ok(u64::from_le_bytes(bytes))
}

// Re-encode the counter back into the account buffer, little-endian.
fn write_counter(data: &mut [u8], value: u64) -> Result<(), ProgramError> {
    if data.len() < 8 {
        return Err(ProgramError::DataTooSmall);
    }
    data[..8].copy_from_slice(&value.to_le_bytes());
    Ok(())
}

// The "program entry point": stateless code over a mutable account buffer.
fn process_instruction(data: &mut [u8], instruction: &Instruction) -> Result<u64, ProgramError> {
    let current = read_counter(data)?;
    let next = match instruction {
        Instruction::Increment => current + 1, // intentionally unchecked — Exercise 5 asks you to harden this
        Instruction::SetTo(value) => *value,
    };
    write_counter(data, next)?;
    Ok(next)
}

fn main() {
    let mut account = Account {
        owner: "CounterProgram1111",
        data: [0u8; 8],
    };

    // The runtime hands the program a mutable view of account data each call.
    let after_set = process_instruction(&mut account.data, &Instruction::SetTo(41)).unwrap();
    let after_inc = process_instruction(&mut account.data, &Instruction::Increment).unwrap();

    let final_counter = read_counter(&account.data).unwrap();

    println!("after set = {}", after_set);
    println!("after increment = {}", after_inc);
    println!("counter = {}", final_counter);
    println!("owner = {}", account.owner);
}

smart_contract_platform_compare:
// The Solana vs Sei(CosmWasm) vs EVM mental model, encoded as data.
//
// Every on-chain platform answers the same four questions differently:
//   1. Where does contract state live?
//   2. What does the code actually run as (the execution target)?
//   3. How is data serialized across the host boundary?
//   4. What shape is the entry point the runtime calls?
//
// We model each platform as an enum variant, attach those four facts, and
// print one line per platform so the contrasts sit side by side.

#[derive(Debug, Clone, Copy)]
enum Platform {
    Solana,
    SeiCosmWasm,
    EvmSolidity,
}

struct PlatformModel {
    name: &'static str,
    state_model: &'static str,
    execution_target: &'static str,
    serialization: &'static str,
    entry_shape: &'static str,
}

fn describe(platform: Platform) -> PlatformModel {
    match platform {
        Platform::Solana => PlatformModel {
            name: "Solana",
            state_model: "external accounts",
            execution_target: "SBF",
            serialization: "Borsh",
            entry_shape: "process_instruction",
        },
        Platform::SeiCosmWasm => PlatformModel {
            name: "Sei/CosmWasm",
            state_model: "contract-owned kv",
            execution_target: "wasm",
            serialization: "JSON/serde",
            entry_shape: "instantiate/execute/query",
        },
        Platform::EvmSolidity => PlatformModel {
            name: "EVM/Solidity",
            state_model: "contract storage",
            execution_target: "EVM bytecode",
            serialization: "ABI",
            entry_shape: "selector dispatch",
        },
    }
}

fn main() {
    let platforms = [Platform::Solana, Platform::SeiCosmWasm, Platform::EvmSolidity];

    for platform in platforms {
        let model = describe(platform);
        println!(
            "{} | state={} | target={} | serde={} | entry={}",
            model.name,
            model.state_model,
            model.execution_target,
            model.serialization,
            model.entry_shape
        );
    }
}

